// The Cypher System SRD's search index (lib/srdIndex.ts has the entry shape),
// generated by scripts/build-cypher-srd-index.ts from the raw scraped JSON in
// public/Cypher_SRD/. Re-run `npm run build:cypher-index` after changing it.

import type { SrdEntry } from "./srdIndex";

// In display order.
export const CYPHER_SRD_CATEGORIES = [
    "Ability", "Artifact", "Character Arc", "Creature", "Cypher", "Descriptor",
    "Equipment", "Flavor", "Focus", "Mutation", "NPC", "Quick Stats", "Rule", "Type", "Glossary",
] as const;

export type CypherSrdCategory = typeof CYPHER_SRD_CATEGORIES[number];
export type CypherSrdEntry = SrdEntry<CypherSrdCategory> & { genre?: string };

export const CYPHER_SRD_INDEX_PATH = "/Cypher_SRD/search-index.json";
